319	OLMo-2 7B & Benefit & 100\% & 82\% & $\tau = 3.25$ \\
320	Qwen2.5-7B & V-recovery & 100\% & 72\% & $\tau = 3.0$ \\
321	\bottomrule
322	\end{tabular}
